import{_ as e,o as d,c as a,a3 as o}from"./chunks/framework.BrO6lPIi.js";const b=JSON.parse('{"title":"语音输入（本地 STT）","description":"语音输入（本地 STT）让用户用说的代替打字：在侧边栏点 🎤 说话，识别结果只写进输入框草稿，**不会自动发送**，也不触发任何工具调用。","frontmatter":{"title":"语音输入（本地 STT）","description":"语音输入（本地 STT）让用户用说的代替打字：在侧边栏点 🎤 说话，识别结果只写进输入框草稿，**不会自动发送**，也不触发任何工具调用。"},"headers":[],"relativePath":"语音输入/index.md","filePath":"语音输入/index.md","lastUpdated":null}'),r={name:"语音输入/index.md"};function s(c,t,i,l,n,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="语音输入-本地-stt" tabindex="-1">语音输入（本地 STT） <a class="header-anchor" href="#语音输入-本地-stt" aria-label="Permalink to &quot;语音输入（本地 STT）&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/voice-input.js" target="_blank" rel="noreferrer">src/side_panel/voice-input.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/voice-capture-worklet.js" target="_blank" rel="noreferrer">src/side_panel/voice-capture-worklet.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/routes.js" target="_blank" rel="noreferrer">agent/src/asr/routes.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/config.js" target="_blank" rel="noreferrer">agent/src/asr/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/detect.js" target="_blank" rel="noreferrer">agent/src/asr/detect.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/install.js" target="_blank" rel="noreferrer">agent/src/asr/install.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/asr/session.js" target="_blank" rel="noreferrer">agent/src/asr/session.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/side_panel.html" target="_blank" rel="noreferrer">side_panel.html</a></li></ul></details><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>语音输入（本地 STT）让用户用说的代替打字：在侧边栏点 🎤 说话，识别结果只写进输入框草稿，<strong>不会自动发送</strong>，也不触发任何工具调用。识别完全在本地 Agent 进程内跑 ONNX 模型，音频不出本机、不写盘。</p><p>它与 RAG、长期记忆一样属于<strong>可选组件</strong>：默认关闭，未配置时扩展端不会尝试加载任何语音相关资源，未安装依赖的用户不会为 ONNX 运行时多付一次常驻内存。</p><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#设计目标与边界">设计目标与边界</a></li><li><a href="#三段式门控">三段式门控</a></li><li><a href="#启用流程">启用流程</a></li><li><a href="#使用体验">使用体验</a></li><li><a href="#配置项">配置项</a></li><li><a href="#接口一览">接口一览</a></li><li><a href="#数据与隐私">数据与隐私</a></li><li><a href="#资源控制">资源控制</a></li><li><a href="#故障排查">故障排查</a></li><li><a href="#结论">结论</a></li></ol><h2 id="设计目标与边界" tabindex="-1">设计目标与边界 <a class="header-anchor" href="#设计目标与边界" aria-label="Permalink to &quot;设计目标与边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>落地方式</th></tr></thead><tbody><tr><td>音频不出本机</td><td>采集、编码、推理全在本机；不上传、不写临时文件</td></tr><tr><td>装了不该自动生效</td><td><code>DEFAULT_ASR_CONFIG.enabled = false</code>，且 UI 门控要求三项同时就绪</td></tr><tr><td>不拖累主链路</td><td>定稿推理在独立 worker 线程，Agent 事件循环不被阻塞</td></tr><tr><td>出错不装死</td><td>依赖缺失 → 按钮直接隐藏；推理失败 → 退回流式文本</td></tr><tr><td>内存可控</td><td>会话空闲回收、录音时长上限、RSS 保护、引擎空闲卸载</td></tr></tbody></table><p>明确不做的事：</p><ul><li><strong>不做自动重装</strong>：<code>sherpa-onnx-node</code> 包体约 300MB+，静默重装会在用户无感知时拉满带宽，只记录 <code>everSucceeded</code> 并提示用户点击「重新安装」。</li><li><strong>不做侧边栏麦克风授权弹窗</strong>：Chromium 在侧边栏 / 弹窗形态下不允许弹授权框，授权入口放在选项页的标签页上下文里。</li><li><strong>不接管发送</strong>：识别结果只作为草稿插入，是否发送由用户决定。</li></ul><h2 id="三段式门控" tabindex="-1">三段式门控 <a class="header-anchor" href="#三段式门控" aria-label="Permalink to &quot;三段式门控&quot;">​</a></h2><p>🎤 按钮是否出现，由三个彼此独立的信号共同决定，任一为假即隐藏（避免「点了才报错」）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>deps.ready（依赖就绪） × modelsReady（模型就绪） × enabled（用户开关）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>信号</th><th>事实来源</th><th>说明</th></tr></thead><tbody><tr><td><code>deps.ready</code></td><td><code>AI_HELPER_ASR_DEPS</code> 未置 0 且磁盘存在 <code>node_modules/sherpa-onnx-node/package.json</code>，并通过子进程探测</td><td>零成本磁盘判定在前，子进程 <code>require</code> 确认在后</td></tr><tr><td><code>modelsReady</code></td><td><code>/api/asr/status</code> 返回的能力汇总 <code>capability.offline || capability.online</code></td><td>至少有一个 <code>offline</code>（定稿）或 <code>online</code>（流式）模型包通过校验</td></tr><tr><td><code>enabled</code></td><td><code>asr-config.json</code> 的 <code>enabled</code> 字段</td><td>默认 <code>false</code>，只能由用户显式打开</td></tr></tbody></table><p>三者由代理端在 <code>/api/asr/status</code> 里汇总成 <code>available</code> 一次，扩展端直接采信；只缺一环时 <code>reason</code> 会区分 <code>deps_missing</code> / <code>models_missing</code> / <code>disabled</code>，配置页据此提示补哪一项。</p><p>门控状态在扩展端由 <code>refreshGating()</code> 拉取，点 🎤 前会再复查一次，避免状态陈旧。</p><h2 id="启用流程" tabindex="-1">启用流程 <a class="header-anchor" href="#启用流程" aria-label="Permalink to &quot;启用流程&quot;">​</a></h2><ol><li><strong>安装依赖</strong>：选项页「语音」标签页显示检测结果，缺失时点「一键安装」；等价命令行是 <code>aha asr install</code>，或在安装 Agent 时加 <code>--with-asr</code>。</li><li><strong>准备模型</strong>：把模型包放进 <code>~/.ai-helper-agent/asr/models/&lt;id&gt;/</code>（每包一个目录，内含 <code>manifest.json</code>），可点「扫描」重扫，或用「从文件夹导入」；也可点「下载」从内置目录拉取。</li><li><strong>打开开关</strong>：在「语音」标签页打开总开关，按需选识别语言（<code>auto</code> / 中文 / 英文 / 日文 / 韩文 / 粤语）。</li><li><strong>授权麦克风</strong>：点「去授权」，在打开的标签页里允许一次；未授权时录音条里也会出现「去授权」按钮。</li></ol><p>三项就绪后，侧边栏输入框右侧出现 🎤。</p><h2 id="使用体验" tabindex="-1">使用体验 <a class="header-anchor" href="#使用体验" aria-label="Permalink to &quot;使用体验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作</th><th>行为</th></tr></thead><tbody><tr><td>点 🎤 / 按 <code>Alt+V</code></td><td>开始录音，录音条展开（音量柱 + 计时 + 状态文本 + 取消 / 完成）</td></tr><tr><td>说话过程中</td><td>流式草稿实时刷新（服务端节流 150ms），已定稿片段不再回改</td></tr><tr><td>按 <code>Alt+V</code> / 点「完成」</td><td>停止采集并发起定稿，用整段高精度模型重转一遍</td></tr><tr><td>按 <code>Esc</code> / 点「取消」</td><td>放弃本次录音，草稿不落输入框</td></tr><tr><td>静音超时</td><td>5 分钟上限自动结束并定稿</td></tr></tbody></table><p>录音条的键盘可达性有两处刻意处理：</p><ul><li>隐藏前先把焦点交还输入框（<code>releaseBarFocus()</code>）。点「取消 / 完成」时焦点留在按钮上，若紧接着给整条设 <code>aria-hidden=&quot;true&quot;</code>，Chrome 122+ 会拦截并告警 <code>Blocked aria-hidden on an element because its descendant retained focus</code>，键盘与读屏用户的焦点还会被悬空。</li><li><code>role=&quot;status&quot;</code> / <code>aria-live=&quot;polite&quot;</code> 只挂在状态文本 <code>#voiceStatusText</code> 上，而不是整条录音条。否则每 200ms 刷新的计时器会被读屏反复朗读，形成刷屏。</li></ul><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h2><p>用户配置落在 <code>~/.ai-helper-agent/asr/asr-config.json</code>（缺失即视为从未配置，一律按未启用处理）：</p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>false</code></td><td>总开关</td></tr><tr><td><code>language</code></td><td><code>auto</code></td><td>取值 <code>auto</code> / <code>zh</code> / <code>en</code> / <code>ja</code> / <code>ko</code> / <code>yue</code></td></tr><tr><td><code>streamingModelId</code></td><td><code>null</code></td><td>流式草稿模型包 id；<code>null</code> 表示按能力自动选第一个可用包</td></tr><tr><td><code>offlineModelId</code></td><td><code>null</code></td><td>定稿模型包 id；同上</td></tr><tr><td><code>idleUnloadMs</code></td><td><code>600000</code></td><td>引擎空闲卸载毫秒数，<code>0</code> 表示不卸载</td></tr></tbody></table><p>写入走「临时文件 + rename」，避免读到写一半的 JSON；读取时对类型不符的字段一律回落默认值（<code>sanitizeAsrConfig</code>）。</p><h2 id="接口一览" tabindex="-1">接口一览 <a class="header-anchor" href="#接口一览" aria-label="Permalink to &quot;接口一览&quot;">​</a></h2><p>HTTP 端点（均需 Bearer Token）：</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/asr/status</code></td><td>依赖 / 模型 / 开关 / 已加载引擎状态</td></tr><tr><td>POST</td><td><code>/api/asr/config</code></td><td>修改开关、语言、模型 id、空闲卸载</td></tr><tr><td>GET</td><td><code>/api/asr/models</code></td><td>已扫描模型包列表（非法包附原因）</td></tr><tr><td>POST</td><td><code>/api/asr/models/scan</code></td><td>重新扫描模型目录</td></tr><tr><td>POST</td><td><code>/api/asr/models/pick</code></td><td>从文件夹导入模型包</td></tr><tr><td>DELETE</td><td><code>/api/asr/models/:id</code></td><td>删除模型包</td></tr><tr><td>POST</td><td><code>/api/asr/models/download</code></td><td>按内置目录下载模型</td></tr><tr><td>GET</td><td><code>/api/asr/models/download/status</code></td><td>下载进度</td></tr><tr><td>POST</td><td><code>/api/asr/models/download/cancel</code></td><td>取消下载</td></tr><tr><td>GET</td><td><code>/api/asr/models/catalog</code></td><td>内置推荐模型清单</td></tr><tr><td>POST</td><td><code>/api/asr/transcribe</code></td><td>整段音频一次性转写</td></tr><tr><td>POST</td><td><code>/api/asr/warmup</code></td><td>预热引擎</td></tr><tr><td>POST</td><td><code>/api/asr/deps/install</code></td><td>一键安装依赖</td></tr><tr><td>GET</td><td><code>/api/asr/deps/install/status</code></td><td>安装进度</td></tr><tr><td>POST</td><td><code>/api/asr/deps/detect</code></td><td>重新检测依赖</td></tr></tbody></table><p>WebSocket：<code>ws://127.0.0.1:18910/ws/asr/:sessionId</code>，鉴权与 <code>/ws/exec</code> 一致（Header 优先，回退 <code>?token=</code>），依赖不可用时直接 503 拒连。帧协议与定稿流程见 <strong><a href="/ai-helper/wiki/语音输入/流式会话与定稿引擎/">流式会话与定稿引擎</a></strong>。</p><h2 id="数据与隐私" tabindex="-1">数据与隐私 <a class="header-anchor" href="#数据与隐私" aria-label="Permalink to &quot;数据与隐私&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.ai-helper-agent/asr/</span></span>
<span class="line"><span>├── asr-config.json     # 用户配置</span></span>
<span class="line"><span>├── hash-cache.json     # 模型文件 sha256 缓存（按 path+size+mtime 失效）</span></span>
<span class="line"><span>└── models/&lt;id&gt;/        # 模型包（manifest.json + ONNX 文件）</span></span></code></pre></div><p>音频只在内存中流转：采集为 16kHz PCM，切片后经 WebSocket 上送，既不落盘也不出网。识别文本只写进侧边栏输入框，随会话内容进入正常的对话存储路径。</p><h2 id="资源控制" tabindex="-1">资源控制 <a class="header-anchor" href="#资源控制" aria-label="Permalink to &quot;资源控制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>约束</th></tr></thead><tbody><tr><td>单次录音上限</td><td><code>MAX_RECORDING_MS</code>，默认 5 分钟</td></tr><tr><td>会话空闲回收</td><td><code>SESSION_IDLE_MS</code>，默认 30 秒无帧即释放</td></tr><tr><td>并发会话</td><td><code>MAX_SESSIONS</code>，默认 1（第二个请求直接回 <code>busy</code>）</td></tr><tr><td>RSS 保护</td><td>超过 <code>RSS_LIMIT_BYTES</code>（默认 3.5GB）跳过 offline 定稿，改用流式文本（<code>fallback: true</code>）</td></tr><tr><td>引擎空闲卸载</td><td><code>idleUnloadMs</code> 默认 10 分钟</td></tr><tr><td>依赖探测开销</td><td>零成本磁盘判定优先；需子进程确认时超时 3 秒</td></tr></tbody></table><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><p><strong>🎤 按钮不出现</strong>：三项门控里至少有一项为假。打开选项页「语音」Tab，按提示补齐依赖、模型或开关。</p><p><strong>提示没有麦克风权限</strong>：侧边栏形态下无法弹授权框，去选项页点「去授权」，在标签页里允许一次。</p><p><strong>模型包显示「非法」</strong>：<code>manifest.json</code> 校验失败，常见原因是 <code>schema</code> 不是 1、<code>engine</code> 不是 <code>sherpa-onnx</code>、<code>kind</code> 不在 <code>online</code> / <code>offline</code> / <code>vad</code> 内、<code>files</code> 列出的文件缺失或为空、<code>sha256</code> 与文件实际摘要不符。错误原因随列表一并返回。</p><p><strong>连接被拒（503）</strong>：依赖不可用。此时扩展端不会开流式通道，需先完成依赖安装。</p><p><strong>定稿文本明显弱于预期</strong>：可能命中 RSS 保护退化为流式文本。查看 <code>/api/asr/status</code> 的已加载引擎与最近一次结果标记。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>语音输入的工程重心不在「接一个 ASR 模型」，而在<strong>可选性</strong>与<strong>不打扰</strong>：默认关闭、三段式门控、隐藏而非报错、音频不出本机、推理不占主线程、内存有明确上限。按此边界，它可以作为一个可插拔的输入方式长期存在，而不成为扩展主链路的负担。</p>`,45)])])}const g=e(r,[["render",s]]);export{b as __pageData,g as default};
